const items = $input.all();

// Google Calendar는 결과가 없어도 빈 item을 반환할 수 있으므로 start 있는 것만 추린다
const events = items
  .map(i => i.json)
  .filter(e => e && e.start && (e.start.dateTime || e.start.date));

const WD = ['일', '월', '화', '수', '목', '금', '토'];

function fmtDate(d) {
  return `${d.getMonth() + 1}/${d.getDate()}(${WD[d.getDay()]})`;
}
function fmtTime(d) {
  const hh = String(d.getHours()).padStart(2, '0');
  const mm = String(d.getMinutes()).padStart(2, '0');
  return `${hh}:${mm}`;
}

const weekStart = $now.startOf('week');
const rangeLabel = `${weekStart.toFormat('yyyy-MM-dd')} ~ ${weekStart.plus({ days: 6 }).toFormat('yyyy-MM-dd')}`;

if (!events.length) {
  return [{ json: { text: `:calendar: *이번 주 일정* (${rangeLabel})\n\n이번 주 등록된 일정이 없습니다.` } }];
}

// 요일별 그룹핑
const groups = {};
for (const e of events) {
  const isAllDay = !!(e.start.date && !e.start.dateTime);
  const startRaw = e.start.dateTime || e.start.date;
  const start = new Date(startRaw);
  // 종일 일정은 UTC 자정 기준이므로 날짜 문자열 그대로 키로 사용
  const dayKey = isAllDay ? e.start.date : start.toISOString().slice(0, 10);

  const summary = e.summary || '(제목 없음)';
  let line;
  if (isAllDay) {
    line = `• 종일 – ${summary}`;
  } else {
    const endRaw = e.end && (e.end.dateTime || e.end.date);
    const end = endRaw ? new Date(endRaw) : null;
    const timeStr = end ? `${fmtTime(start)}–${fmtTime(end)}` : fmtTime(start);
    line = `• ${timeStr} – ${summary}`;
  }
  if (e.location) line += ` @ ${e.location}`;

  const labelDate = isAllDay ? new Date(e.start.date + 'T00:00:00') : start;
  if (!groups[dayKey]) groups[dayKey] = { date: labelDate, lines: [] };
  groups[dayKey].lines.push(line);
}

const sortedKeys = Object.keys(groups).sort();
let body = '';
for (const k of sortedKeys) {
  const g = groups[k];
  body += `\n*${fmtDate(g.date)}*\n${g.lines.join('\n')}\n`;
}

const text = `:calendar: *이번 주 일정* (${rangeLabel})\n${body}`;
return [{ json: { text } }];
